with subscriptions_by_customer as (select customer_id, sum(case when plan = 'premium' then monthly_fee else 0 end) as premium_monthly_fee from subscriptions group by customer_id) select customers.id, customers.country, subscriptions_by_customer.premium_monthly_fee from customers inner join subscriptions_by_customer on customers.id = subscriptions_by_customer.customer_id order by id asc limit 5;
